namespace Ets.Core.Domain.Models;

/// <summary>
///     Base for entities: equality is identity, never attribute values.
/// </summary>
/// <typeparam name="TId">The typed id, generated by the domain through <c>IIdGenerator</c> at creation.</typeparam>
/// <remarks>
///     The store never allocates keys (ADR-0014), so an entity has its id from the moment it exists and
///     two unsaved entities are never accidentally equal.
/// </remarks>
[System.Diagnostics.CodeAnalysis.SuppressMessage(
    "Major Code Smell",
    "S4035:Classes implementing \"IEquatable<T>\" should be sealed",
    Justification = "Entity is a base class by design; Equals compares the runtime type, so subtypes never equal each other.")]
public abstract class Entity<TId> : IEntity<TId>, IEquatable<Entity<TId>>
    where TId : struct
{
    protected Entity(TId id)
    {
        Id = id;
    }

    /// <summary>
    ///     For rehydration only: event-sourced aggregates are created empty and get their id from their
    ///     creation event; EF Core materialises through it.
    /// </summary>
    protected Entity()
    {
    }

    [UsedImplicitly] public TId Id { get; protected set; }

    public static bool operator ==(Entity<TId>? left, Entity<TId>? right) => Equals(left, right);

    public static bool operator !=(Entity<TId>? left, Entity<TId>? right) => !Equals(left, right);

    public bool Equals(Entity<TId>? other)
    {
        if (other is null)
        {
            return false;
        }

        if (ReferenceEquals(this, other))
        {
            return true;
        }

        return other.GetType() == GetType() && EqualityComparer<TId>.Default.Equals(Id, other.Id);
    }

    public override bool Equals(object? obj)
    {
        return obj is Entity<TId> entity && Equals(entity);
    }

    public override int GetHashCode()
    {
        return HashCode.Combine(GetType(), Id);
    }
}
